package io.knowledgebrain.space;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.flywaydb.core.Flyway;
import org.postgresql.ds.PGSimpleDataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.web.server.ResponseStatusException;
import static org.assertj.core.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_SPACE_DATABASE_URL",matches=".+")
class GroupMembershipIntegrationTest {
 PGSimpleDataSource source;JdbcTemplate jdbc;GroupSpaceStore spaces;GroupMembershipStore store;UuidV7 ids=new UuidV7(Clock.systemUTC());UUID owner,group,space;String trace="a".repeat(32);Clock clock;String secret=Base64.getUrlEncoder().withoutPadding().encodeToString(new byte[32]);
 String key(){return UUID.randomUUID().toString().replace("-","");}
 GroupMembershipStore at(Instant now){return new GroupMembershipStore(source,Clock.fixed(now,ZoneOffset.UTC),new GroupInvitationCodes(secret));}
 @BeforeEach void setup(){source=new PGSimpleDataSource();source.setURL(System.getenv("BRAIN_TEST_SPACE_DATABASE_URL"));source.setUser("brain_space");source.setPassword(System.getenv("BRAIN_TEST_SPACE_DATABASE_PASSWORD"));Flyway.configure().dataSource(source).load().migrate();jdbc=new JdbcTemplate(source);spaces=new GroupSpaceStore(source,Clock.systemUTC());owner=ids.next();group=ids.next();space=spaces.provision(group,owner,trace).spaceId();clock=Clock.fixed(Instant.now(),ZoneOffset.UTC);store=at(clock.instant());}
 @Test void issueAcceptAndRoleHistoryContainNoCredential()throws Exception{var issued=store.issue(group,owner,key(),"MEMBER",trace);assertThat(issued.code()).hasSize(43);assertThat(store.invitations(group,owner,null,20)).hasSize(1);var principal=ids.next();var m=store.accept(principal,issued.code(),trace);assertThat(m.role()).isEqualTo("MEMBER");assertThat(m.version()).isEqualTo(1);assertThat(spaces.access(principal,List.of(group))).isEmpty();assertThat(spaces.participation(principal,List.of(group))).extracting(GroupSpaceStore.Grant::role).containsExactly("MEMBER");assertThat(store.invitationHistory(group,owner,issued.invitation().invitationId(),Long.MAX_VALUE,10)).extracting(GroupMembershipStore.InvitationRevision::state).containsExactly("ACCEPTED","PENDING");assertThat(store.memberHistory(group,owner,principal,Long.MAX_VALUE,10)).extracting(GroupMembershipStore.MemberRevision::reason).containsExactly("JOINED");for(var bytes:jdbc.queryForList("SELECT payload FROM outbox_event WHERE aggregateid IN (?,?)",byte[].class,space,issued.invitation().invitationId()))assertThat(new String(bytes,java.nio.charset.StandardCharsets.ISO_8859_1)).doesNotContain(issued.code());var json=jdbc.queryForObject("SELECT to_jsonb(i)::text FROM group_invitation i WHERE invitation_id=?",String.class,issued.invitation().invitationId());assertThat(json).doesNotContain(issued.code());assertThat(store.memberHistory(group,owner,owner,Long.MAX_VALUE,10)).hasSize(1);}
 @Test void creationReplaySurvivesRestartAndDoesNotDuplicate(){var key=key();var issued=store.issue(group,owner,key,"VIEWER",trace);var replay=at(clock.instant().plusSeconds(5)).issue(group,owner,key,"VIEWER",trace);assertThat(replay).isEqualTo(issued);assertThatThrownBy(()->store.issue(group,owner,key,"MEMBER",trace)).isInstanceOf(ResponseStatusException.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregateid=?",Long.class,issued.invitation().invitationId())).isEqualTo(1);}
 @Test void oneUseConcurrencyHasOnlyOneWinner()throws Exception{var issued=store.issue(group,owner,key(),"MEMBER",trace);try(var executor=Executors.newVirtualThreadPerTaskExecutor()){var tasks=new ArrayList<Future<UUID>>();for(int i=0;i<6;i++){var actor=ids.next();tasks.add(executor.submit(()->{try{return store.accept(actor,issued.code(),trace).principalId();}catch(ResponseStatusException e){assertThat(e.getStatusCode().value()).isEqualTo(410);return null;}}));}var winners=new ArrayList<UUID>();for(var task:tasks){var actor=task.get(20,TimeUnit.SECONDS);if(actor!=null)winners.add(actor);}assertThat(winners).hasSize(1);assertThat(store.accept(winners.getFirst(),issued.code(),trace).version()).isEqualTo(1);assertThat(store.members(group,owner,null,20)).hasSize(2);assertThat(jdbc.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregateid=?",Long.class,issued.invitation().invitationId())).isEqualTo(2);}}
 @Test void revokeAndExpiryAreAuthoritative(){var issued=store.issue(group,owner,key(),"MEMBER",trace);var revoked=store.revoke(group,owner,issued.invitation().invitationId(),1,trace);assertThat(revoked.state()).isEqualTo("REVOKED");assertThatThrownBy(()->store.accept(ids.next(),issued.code(),trace)).isInstanceOf(ResponseStatusException.class);var second=store.issue(group,owner,key(),"VIEWER",trace);var later=at(second.invitation().expiresAt());assertThat(later.invitations(group,owner,null,20)).anyMatch(i->i.invitationId().equals(second.invitation().invitationId())&&i.state().equals("EXPIRED"));assertThatThrownBy(()->later.accept(ids.next(),second.code(),trace)).isInstanceOf(ResponseStatusException.class);assertThat(later.issue(group,owner,jdbc.queryForObject("SELECT request_key FROM group_invitation WHERE invitation_id=?",String.class,second.invitation().invitationId()),"VIEWER",trace).code()).isNull();}
 @Test void memberAndViewerCannotAdministerOrEscalate(){for(String role:List.of("MEMBER","VIEWER")){var actor=ids.next();var issued=store.issue(group,owner,key(),role,trace);store.accept(actor,issued.code(),trace);assertThatThrownBy(()->store.issue(group,actor,key(),"MEMBER",trace)).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->store.members(group,actor,null,20)).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->store.change(group,actor,actor,1,"MEMBER",trace)).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->store.revoke(group,actor,issued.invitation().invitationId(),2,trace)).isInstanceOf(ResponseStatusException.class);}for(String role:List.of("OWNER","ADMIN","EDITOR","INVALID"))assertThatThrownBy(()->store.issue(group,owner,key(),role,trace)).isInstanceOf(ResponseStatusException.class);}
 @Test void ownerCannotLeaveDemoteOrBeRemoved(){assertThatThrownBy(()->store.retire(group,owner,owner,1,true,trace)).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->store.retire(group,owner,owner,1,false,trace)).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->store.change(group,owner,owner,1,"VIEWER",trace)).isInstanceOf(ResponseStatusException.class);var invite=store.issue(group,owner,key(),"MEMBER",trace);assertThatThrownBy(()->store.accept(owner,invite.code(),trace)).isInstanceOf(ResponseStatusException.class);assertThat(store.invitations(group,owner,null,20).getFirst().state()).isEqualTo("PENDING");}
 @Test void acceptedReplayNeverOverridesChangedRoleOrRestoresRemoval(){var actor=ids.next();var issued=store.issue(group,owner,key(),"MEMBER",trace);store.accept(actor,issued.code(),trace);assertThat(store.change(group,owner,actor,1,"VIEWER",trace).version()).isEqualTo(2);assertThat(store.accept(actor,issued.code(),trace).role()).isEqualTo("VIEWER");assertThatThrownBy(()->store.change(group,owner,actor,1,"MEMBER",trace)).isInstanceOf(ResponseStatusException.class);store.retire(group,owner,actor,2,false,trace);assertThatThrownBy(()->store.accept(actor,issued.code(),trace)).isInstanceOf(ResponseStatusException.class);assertThat(spaces.participation(actor,List.of(group))).isEmpty();var replacement=store.issue(group,owner,key(),"MEMBER",trace);var restored=store.accept(actor,replacement.code(),trace);assertThat(restored.version()).isEqualTo(4);assertThat(store.memberHistory(group,owner,actor,Long.MAX_VALUE,10)).extracting(GroupMembershipStore.MemberRevision::version).containsExactly(4L,3L,2L,1L);}
 @Test void selfLeaveRevokesParticipationAndRequiresNewInvitation(){var actor=ids.next();var issued=store.issue(group,owner,key(),"VIEWER",trace);store.accept(actor,issued.code(),trace);assertThat(store.retire(group,actor,actor,1,true,trace).state()).isEqualTo("RETIRED");assertThatThrownBy(()->store.self(group,actor)).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->store.accept(actor,issued.code(),trace)).isInstanceOf(ResponseStatusException.class);assertThat(spaces.participations(actor,null,20).grants()).isEmpty();}
 @Test void invitationAndAcceptanceOutboxFailuresRollBackAllLocalState(){assertThatThrownBy(()->store.issue(group,owner,key(),"MEMBER","0".repeat(32))).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(store.invitations(group,owner,null,20)).isEmpty();var issued=store.issue(group,owner,key(),"MEMBER",trace);var actor=ids.next();assertThatThrownBy(()->store.accept(actor,issued.code(),"0".repeat(32))).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(store.members(group,owner,null,20)).hasSize(1);assertThat(store.invitations(group,owner,null,20).getFirst().state()).isEqualTo("PENDING");assertThat(store.accept(actor,issued.code(),trace).version()).isEqualTo(1);}
 @Test void changeAndRemovalOutboxFailuresRollBackVersionAndHistory(){var actor=ids.next();store.accept(actor,store.issue(group,owner,key(),"MEMBER",trace).code(),trace);assertThatThrownBy(()->store.change(group,owner,actor,1,"VIEWER","0".repeat(32))).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThatThrownBy(()->store.retire(group,owner,actor,1,false,"0".repeat(32))).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(store.self(group,actor).version()).isEqualTo(1);assertThat(store.memberHistory(group,owner,actor,Long.MAX_VALUE,10)).hasSize(1);}
 @Test void concurrentRoleChangesRespectVersion()throws Exception{var actor=ids.next();store.accept(actor,store.issue(group,owner,key(),"MEMBER",trace).code(),trace);try(var executor=Executors.newVirtualThreadPerTaskExecutor()){var tasks=new ArrayList<Future<Boolean>>();for(int i=0;i<4;i++)tasks.add(executor.submit(()->{try{store.change(group,owner,actor,1,"VIEWER",trace);return true;}catch(ResponseStatusException e){assertThat(e.getStatusCode().value()).isEqualTo(412);return false;}}));int changed=0;for(var task:tasks)if(task.get(20,TimeUnit.SECONDS))changed++;assertThat(changed).isEqualTo(1);assertThat(store.self(group,actor).version()).isEqualTo(2);}}
 @Test void foreignGroupAndRetiredSpaceAreDenied(){var other=ids.next();assertThatThrownBy(()->store.invitations(group,other,null,20)).isInstanceOf(ResponseStatusException.class);var invite=store.issue(group,owner,key(),"VIEWER",trace);jdbc.update("UPDATE space SET state='RETIRED' WHERE space_id=?",space);assertThatThrownBy(()->store.accept(other,invite.code(),trace)).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->store.members(group,owner,null,20)).isInstanceOf(ResponseStatusException.class);}
 @Test void keyRotationDoesNotChangeAcceptedCredentialsOrInventReplayCode(){var key=key();var issued=store.issue(group,owner,key,"MEMBER",trace);var bytes=new byte[32];Arrays.fill(bytes,(byte)1);var rotated=new GroupMembershipStore(source,clock,new GroupInvitationCodes(Base64.getUrlEncoder().withoutPadding().encodeToString(bytes)));assertThatThrownBy(()->rotated.issue(group,owner,key,"MEMBER",trace)).isInstanceOf(ResponseStatusException.class);assertThat(rotated.accept(ids.next(),issued.code(),trace).state()).isEqualTo("ACTIVE");}
 @Test void pagesAndHistoryAreKeysetBounded(){for(int i=0;i<3;i++)store.issue(group,owner,key(),"MEMBER",trace);var first=store.invitations(group,owner,null,2);assertThat(first).hasSize(3);assertThat(store.invitations(group,owner,first.get(1).invitationId(),2)).extracting(GroupMembershipStore.Invitation::invitationId).containsExactly(first.get(2).invitationId());assertThat(store.memberHistory(group,owner,owner,1,10)).isEmpty();}
}
